#pragma once
static thread_local bool streamingReadForbidden=false;
struct StreamingReaderState {std::atomic<bool> fail{false},wrongThread{false};std::atomic<int> reads{0};};
class StreamingFixtureReader final:public AudioFormatReader {
public:
    StreamingFixtureReader(std::shared_ptr<StreamingReaderState> s,int64_t count=200000,double rate=48000,int channels=2):AudioFormatReader(nullptr,"stream-fixture"),state(std::move(s)){sampleRate=rate;lengthInSamples=count;numChannels=(unsigned)channels;bitsPerSample=32;usesFloatingPointData=true;}
    static float value(int64_t frame,int channel){float x=(float)(frame%997)/997.f*.6f-.3f;return channel==0?x:-x*.5f;}
    bool readSamples(int* const* dest,int channels,int offset,int64 start,int count)override{
        ++state->reads;if(streamingReadForbidden)state->wrongThread=true;if(state->fail)return false;
        for(int ch=0;ch<channels;++ch)if(dest[ch])for(int i=0;i<count;++i)reinterpret_cast<float*>(dest[ch])[offset+i]=value(start+i,ch);
        return true;
    }
private:std::shared_ptr<StreamingReaderState> state;
};
static bool waitStreaming(const std::function<bool()>& condition,int ms=2500){for(int i=0;i<ms/2;++i){if(condition())return true;Thread::sleep(2);}return condition();}
static bool streamingFixture(const File& file,int frames=2200000){
    TemporaryFile temp(file);std::unique_ptr<OutputStream> out(temp.getFile().createOutputStream());auto writer=out?WavAudioFormat().createWriterFor(out,AudioFormatWriterOptions{}.withSampleRate(48000).withNumChannels(2).withBitsPerSample(32).withSampleFormat(AudioFormatWriterOptions::SampleFormat::floatingPoint)):nullptr;
    if(!writer)return false;AudioBuffer<float> block(2,4096);for(int pos=0;pos<frames;pos+=4096){int n=jmin(4096,frames-pos);for(int ch=0;ch<2;++ch)for(int i=0;i<n;++i)block.setSample(ch,i,StreamingFixtureReader::value(pos+i,ch));if(!writer->writeFromAudioSampleBuffer(block,0,n))return false;}writer.reset();out.reset();return temp.overwriteTargetFileWithTemporary();
}
