        bool exact=true;std::thread audio([&]{streamingReadForbidden=true;for(int n=0;n<25000;++n){float l=0,r=0;double p=n+.375;bool ok=stream->sample(p,l,r);float a=StreamingFixtureReader::value(n,0),b=StreamingFixtureReader::value(n+1,0);exact&=ok&&l==a+.375f*(b-a)&&r==l*-.5f;}streamingReadForbidden=false;});audio.join();
